  switch (normalizeDestination(destination)) {
    case 'NORTH': return { kind: 'route', dock: 1 };
    case 'SOUTH': return { kind: 'route', dock: 2 };
    default: return { kind: 'invalid', reason: 'Unknown destination' };
  }
}

